def count_cycles(m):
    if m <= 1:
        return 0

    visited = [False] * m  # Index 0 is unused, indices 1 to m-1 are used
    num_cycles = 0

    for start_node in range(1, m):
        if not visited[start_node]:
            num_cycles += 1
            current = start_node

            # Trace the cycle
            while not visited[current]:
                visited[current] = True
                # Calculate the next element: 3 * current mod m
                current = (3 * current) % m

    return num_cycles

def solve():
    m_values = []
    # We search downwards from m=199
    for m in range(199, 1, -1):
        # Constraint: m is not divisible by 3
        if m % 3 == 0:
            continue

        C = count_cycles(m)
        if C % 2 != 0:
            m_values.append(m)

    if len(m_values) < 2:
        return "Less than two solutions found"

    # The list m_values is sorted descendingly by the loop structure
    m1 = m_values[0]
    m2 = m_values[1]

    return f"Largest (m1): {m1}, Second Largest (m2): {m2}"

print(solve())
